import java.util.*;

public class Main {
    String countAndSay(int n) {
        String term = "1";                                       // term 1 is always the string "1"
        for (int t = 1; t < n; t++) {                              // build term 2, then 3, all the way through term n
            String nextTerm = "";                                    // start this term's string from scratch
            int i = 0;
            while (i < term.length()) {
                char digit = term.charAt(i);
                int count = 1;
                while (i + count < term.length() && term.charAt(i + count) == digit) {
                    count++;                                              // extend the run while the same digit repeats
                }
                nextTerm += String.valueOf(count) + digit;                // re-creates a brand new String on every append
                i += count;
            }
            term = nextTerm;
        }
        return term;
    }

    public static void main(String[] args) {
        int n = 5;
        Main solution = new Main();
        System.out.println(solution.countAndSay(n));
    }
}

