string countAndSay(int n) {
    string term = "1";
    for (int t = 1; t < n; t++) {
        string nextTerm;
        nextTerm.reserve(term.size() * 2);                        // pre-size the buffer to avoid repeated reallocation
        int i = 0;
        while (i < (int)term.size()) {
            char digit = term[i];
            int count = 1;
            while (i + count < (int)term.size() && term[i + count] == digit) {
                count++;
            }
            nextTerm += to_string(count);
            nextTerm += digit;                                       // appends in place into the reserved buffer
            i += count;
        }
        term = move(nextTerm);
    }
    return term;
}

int main() {
    int n = 5;
    cout << countAndSay(n) << endl;
    return 0;
}

